  // Overwrites patient allergies using validated patientId without checking doctor/patient assignment
  const { patientId, allergies, severityRating } = req.validated;

  const record = await PatientAllergyRecord.findOneAndUpdate(
    { patientId },
    { allergies, severityRating, lastReviewedAt: new Date() },
    { new: true, upsert: true }
  );

  res.json({ success: true, record });
});

app.listen(7002);

