const express = require('express');
const Joi = require('joi');
const { PatientAllergyRecord } = require('../models/allergies');
const { ClinicalAssignment } = require('../models/clinical');

const app = express();
app.use(express.json());

const allergySchema = Joi.object({
  patientId: Joi.string().alphanum().min(6).max(20).required(),
  allergies: Joi.array().items(Joi.string().max(100)).required(),
  severityRating: Joi.string().valid('MILD', 'MODERATE', 'SEVERE').required()
});

const validateAllergyUpdate = (req, res, next) => {
  const { error, value } = allergySchema.validate({
    ...req.body,
    patientId: req.params.patientId
  });

  if (error) {
    return res.status(400).json({ error: error.details[0].message });
  }
  req.validated = value;
  next();
};

app.put('/api/patients/:patientId/allergies', validateAllergyUpdate, async (req, res) => {
  if (!req.user || !req.user.providerId) {
    return res.status(401).json({ error: 'Clinician authentication required' });
  }

  const { patientId, allergies, severityRating } = req.validated;

  // Confirm clinician has authorized care relationship with target patient
  const isAssigned = await ClinicalAssignment.exists({
    providerId: req.user.providerId,
    patientId: patientId,
    status: 'ACTIVE'
  });

  if (!isAssigned) {
    return res.status(403).json({ error: 'Access denied: provider not assigned to this patient' });
  }

  const record = await PatientAllergyRecord.findOneAndUpdate(
    { patientId },
    {
      allergies,
      severityRating,
      updatedByProviderId: req.user.providerId,
      lastReviewedAt: new Date()
    },
    { new: true, upsert: true }
  );

  res.json({ success: true, record });
});

app.listen(7002);
